def contexto_de_ferramentas(nomes_chamados):
    """Lista de schemas: nucleo inteiro + todo modulo que contenha qualquer
    ferramenta chamada nesse caso (nunca so a ferramenta certa sozinha --
    isso obrigaria o modelo a so preencher argumento, nao a escolher)."""
    nucleo_set = set(NUCLEO)
    nomes = set(nucleo_set)
    for nome in nomes_chamados:
        if nome not in nucleo_set:
            for mod in POR_FERRAMENTA.get(nome, []):
                nomes.update(MODULOS[mod])
        nomes.add(nome)
    return [SCHEMAS[n] for n in sorted(nomes) if n in SCHEMAS]


def montar_exemplo(caso):
    messages = [
        {"role": "system", "content": SYSTEM_PROMPT},
        {"role": "user", "content": caso["frase"]},
    ]
    nomes_chamados = [c[0] for c in caso["chamadas"]]

    if caso["chamadas"]:
        tool_calls = []
        for i, (nome, args, _resultado) in enumerate(caso["chamadas"]):
            tool_calls.append({
                "id": f"call_{i+1}", "type": "function",
                "function": {"name": nome, "arguments": json.dumps(args, ensure_ascii=False)}
            })
        messages.append({"role": "assistant", "content": None, "tool_calls": tool_calls})
        for i, (_nome, _args, resultado) in enumerate(caso["chamadas"]):
            messages.append({"role": "tool", "tool_call_id": f"call_{i+1}", "content": json.dumps(resultado, ensure_ascii=False)})
        if caso["resposta"] is not None:
            messages.append({"role": "assistant", "content": caso["resposta"]})
    else:
        messages.append({"role": "assistant", "content": caso["resposta"]})

    return {"messages": messages, "tools": contexto_de_ferramentas(nomes_chamados)}


def gerar():
    random.seed(7)
    linhas = [montar_exemplo(caso) for caso in CASOS]
    random.shuffle(linhas)

    with open("dataset_jarvis.jsonl", "w", encoding="utf-8") as f:
        for linha in linhas:
            f.write(json.dumps(linha, ensure_ascii=False) + "\n")

    print(f"Gerados {len(linhas)} exemplos em dataset_jarvis.jsonl")
    ferramentas_usadas = set()
    for c in CASOS:
        for nome, _, _ in c["chamadas"]:
            ferramentas_usadas.add(nome)
    print(f"Ferramentas cobertas: {len(ferramentas_usadas)} de {len(SCHEMAS)} existentes no Jarvis")
    sem_ferramenta = sum(1 for c in CASOS if not c["chamadas"])
    print(f"Casos sem chamada de ferramenta (esclarecimento/recusa): {sem_ferramenta}")


if __name__ == "__main__":
    gerar()
